import{_ as e,o as l,c as a,a0 as i}from"./chunks/framework.DYAX5gPL.js";const p=JSON.parse('{"title":"样式指南","description":"","frontmatter":{"title":"样式指南"},"headers":[],"relativePath":"guide/style/intro.md","filePath":"guide/style/intro.md"}'),d={name:"guide/style/intro.md"};function r(n,t,s,g,h,f){return l(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="样式概述" tabindex="-1">样式概述 <a class="header-anchor" href="#样式概述" aria-label="Permalink to &quot;样式概述&quot;">​</a></h1><p>maptalks三维渲染图层引入了丰富的样式系统，以方便用户定制二维或三维数据的样式，包括：</p><ul><li>Symbol样式系统，即点线面数据在地图上的绘制样式，<a href="/guide/style/symbols.html">symbol说明文档</a>。</li><li>三维渲染材质系统，即不同三维渲染算法的材质样式属性，<a href="/guide/style/material.html">材质说明文档</a>。</li></ul><p>三维图层都是基于上述两个样式系统来实现三维场景渲染的。</p><h2 id="矢量渲染插件系统" tabindex="-1">矢量渲染插件系统 <a class="header-anchor" href="#矢量渲染插件系统" aria-label="Permalink to &quot;矢量渲染插件系统&quot;">​</a></h2><p>矢量渲染插件是矢量瓦片图层(VectorTileLayer)以及矢量图层(PointLayer, LineStringLayer, PolygonLayer)内部的渲染程序。</p><p>插件式设计能降低各渲染程序之间的耦合性，并保证了扩展性和可维护性。</p><p>当前版本包括了以下的渲染插件：</p><table tabindex="0"><thead><tr><th style="text-align:left;">插件名</th><th style="text-align:left;">描述</th><th>文档</th></tr></thead><tbody><tr><td style="text-align:left;">icon</td><td style="text-align:left;">为点，线或者面类型数据绘制图标和文字的插件</td><td><a href="/guide/style/plugin-icon.html">文档</a></td></tr><tr><td style="text-align:left;">text</td><td style="text-align:left;">为点，线或者面类型数据绘制文字的插件</td><td><a href="/guide/style/plugin-text.html">文档</a></td></tr><tr><td style="text-align:left;">line</td><td style="text-align:left;">为线或面类型数据绘制线或边框</td><td><a href="/guide/style/plugin-line.html">文档</a></td></tr><tr><td style="text-align:left;">line-gradient</td><td style="text-align:left;">为线类型数据绘制渐变色的线</td><td><a href="/guide/style/plugin-line-gradient.html">文档</a></td></tr><tr><td style="text-align:left;">fill</td><td style="text-align:left;">为面类型数据绘制面填充</td><td><a href="/guide/style/plugin-fill.html">文档</a></td></tr><tr><td style="text-align:left;">native-line</td><td style="text-align:left;">用原生绘制技术，为线或面类型数据绘制线或边框</td><td><a href="/guide/style/plugin-native-line.html">文档</a></td></tr><tr><td style="text-align:left;">native-point</td><td style="text-align:left;">用原生绘制技术，为点，线或面类型数据绘制点</td><td><a href="/guide/style/plugin-native-point.html">文档</a></td></tr><tr><td style="text-align:left;">lit</td><td style="text-align:left;">用pbr材质渲染三维面数据的渲染插件</td><td><a href="/guide/style/plugin-lit.html">文档</a></td></tr><tr><td style="text-align:left;">phong</td><td style="text-align:left;">用phong材质渲染三维面数据的渲染插件</td><td><a href="/guide/style/plugin-phong.html">文档</a></td></tr><tr><td style="text-align:left;">wireframe</td><td style="text-align:left;">用边框材质渲染三维面数据的渲染插件</td><td><a href="/guide/style/plugin-wireframe.html">文档</a></td></tr><tr><td style="text-align:left;">gltf-lit</td><td style="text-align:left;">用pbr材质的GLTF模型渲染点类型数据的渲染插件</td><td><a href="/guide/style/plugin-gltf-lit.html">文档</a></td></tr><tr><td style="text-align:left;">gltf-phong</td><td style="text-align:left;">用phong材质的GLTF模型渲染点类型数据的渲染插件</td><td><a href="/guide/style/plugin-gltf-phong.html">文档</a></td></tr><tr><td style="text-align:left;">water</td><td style="text-align:left;">用真实水体材质渲染面数据的渲染插件</td><td><a href="/guide/style/plugin-water.html">文档</a></td></tr></tbody></table><h2 id="_3dtiles图层样式" tabindex="-1">3DTiles图层样式 <a class="header-anchor" href="#_3dtiles图层样式" aria-label="Permalink to &quot;3DTiles图层样式&quot;">​</a></h2><p>3DTiles图层的样式是基于pbr材质和phong材质实现的，你可以通过定义Geo3DTilesLayer上service中的shader来指定用哪个材质来渲染3dtiles模型。</p><p>同时可以通过自定义service上的material属性，来指定材质的渲染参数。</p><p>material属性中的具体属性可以参考<a href="/guide/style/material.html">材质说明文档</a>。</p><h2 id="可视化样式" tabindex="-1">可视化样式 <a class="header-anchor" href="#可视化样式" aria-label="Permalink to &quot;可视化样式&quot;">​</a></h2><p>待实现</p><blockquote><p>本文档已与 @maptalks/gl-layers 2026 源码核对（api-notes-vt-gl.md）</p></blockquote>',16)])])}const y=e(d,[["render",r]]);export{p as __pageData,y as default};
